mapper.select:
SELECT FROM TBL_DECISION_RECOMMENDATION WHERE RECOMMENDATION_STATUS = 'PENDING' AND DEL_FLAG = '0'
AND ORG_ID = #{orgId}
ORDER BY PRIORITY_LEVEL DESC, CREATE_TIME ASC

SELECT FROM TBL_DECISION_RECOMMENDATION WHERE PRIORITY_LEVEL = #{priorityLevel} AND DEL_FLAG = '0' AND RECOMMENDATION_STATUS = 'PENDING'
AND ORG_ID = #{orgId}
ORDER BY CREATE_TIME DESC

SELECT FROM TBL_DECISION_RECOMMENDATION WHERE PRIORITY_LEVEL IN ('HIGH', 'URGENT') AND DEL_FLAG = '0'
AND ORG_ID = #{orgId}
ORDER BY PRIORITY_LEVEL DESC, EXPECTED_BENEFIT DESC

SELECT RECOMMENDATION_TYPE, RECOMMENDATION_STATUS, PRIORITY_LEVEL, COUNT(*) as recommendationCount, AVG(IMPLEMENTATION_COST) as avgCost, AVG(EXPECTED_BENEFIT) as avgBenefit, AVG(EXPECTED_BENEFIT - IMPLEMENTATION_COST) as netBenefit FROM TBL_DECISION_RECOMMENDATION WHERE DEL_FLAG = '0'
AND ORG_ID = #{orgId}
AND ANALYSIS_SOURCE = #{analysisSource}
GROUP BY RECOMMENDATION_TYPE, RECOMMENDATION_STATUS, PRIORITY_LEVEL ORDER BY RECOMMENDATION_TYPE, PRIORITY_LEVEL, RECOMMENDATION_STATUS

SELECT FROM TBL_DECISION_RECOMMENDATION WHERE ANALYSIS_SOURCE = #{analysisSource} AND SOURCE_ID = #{sourceId} AND DEL_FLAG = '0'
AND ORG_ID = #{orgId}
ORDER BY PRIORITY_LEVEL DESC, CREATE_TIME DESC

SELECT FROM TBL_DECISION_RECOMMENDATION WHERE IMPLEMENTATION_DEADLINE < CURRENT_DATE AND RECOMMENDATION_STATUS = 'PENDING' AND DEL_FLAG = '0'
AND ORG_ID = #{orgId}
ORDER BY IMPLEMENTATION_DEADLINE ASC

SELECT RECOMMENDATION_TYPE, COUNT(*) as recommendationCount, SUM(IMPLEMENTATION_COST) as totalCost, SUM(EXPECTED_BENEFIT) as totalBenefit, SUM(EXPECTED_BENEFIT - IMPLEMENTATION_COST) as netBenefit, AVG(IMPLEMENTATION_COST) as avgCost, AVG(EXPECTED_BENEFIT) as avgBenefit FROM TBL_DECISION_RECOMMENDATION WHERE DEL_FLAG = '0' AND RECOMMENDATION_STATUS IN ('PENDING', 'APPROVED')
AND ORG_ID = #{orgId}
GROUP BY RECOMMENDATION_TYPE ORDER BY netBenefit DESC

SELECT

FROM TBL_DECISION_RECOMMENDATION
WHERE DEL_FLAG = '0'

    AND RECOMMENDATION_NO LIKE '%' || #{recommendationNo} || '%'


    AND RECOMMENDATION_NAME LIKE '%' || #{recommendationName} || '%'


    AND RECOMMENDATION_TYPE = #{recommendationType}


    AND RECOMMENDATION_STATUS = #{recommendationStatus}


    AND PRIORITY = #{priority}


    AND ORG_ID = #{orgId}

ORDER BY CREATE_TIME DESC
